-- 1. Table des indicateurs de corrélation par commune
CREATE TABLE IF NOT EXISTS public.correlation_ndvi_chirps (
    commune_id VARCHAR(50) PRIMARY KEY,
    commune_nom VARCHAR(255) NOT NULL,
    district VARCHAR(100),
    region VARCHAR(100),
    r_lag0 DOUBLE PRECISION,
    r_lag1 DOUBLE PRECISION,
    r_lag2 DOUBLE PRECISION,
    r_lag3 DOUBLE PRECISION,
    delai_optimal_mois INTEGER,
    r_max DOUBLE PRECISION,
    r2_pourcent DOUBLE PRECISION,
    sensibilite_pente DOUBLE PRECISION,
    intercept DOUBLE PRECISION,
    statut_dependance VARCHAR(100),
    nb_mois_analyses INTEGER,
    periode_debut INTEGER,
    periode_fin INTEGER,
    date_mise_a_jour TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_corr_district ON public.correlation_ndvi_chirps(district);
CREATE INDEX IF NOT EXISTS idx_corr_region ON public.correlation_ndvi_chirps(region);
CREATE INDEX IF NOT EXISTS idx_corr_statut ON public.correlation_ndvi_chirps(statut_dependance);

-- 2. Table des séries temporelles couplées mensuelles
CREATE TABLE IF NOT EXISTS public.relation_ndvi_chirps_mensuelle (
    commune_id VARCHAR(50) NOT NULL,
    annee INTEGER NOT NULL,
    mois INTEGER NOT NULL,
    saison VARCHAR(20),
    precip_mm DOUBLE PRECISION,
    ndvi DOUBLE PRECISION,
    ndvi_reference DOUBLE PRECISION,
    anomalie_precip_mm DOUBLE PRECISION,
    anomalie_ndvi DOUBLE PRECISION,
    classe_relation INTEGER,
    PRIMARY KEY (commune_id, annee, mois)
);

CREATE INDEX IF NOT EXISTS idx_rel_annee_mois ON public.relation_ndvi_chirps_mensuelle(annee, mois);
CREATE INDEX IF NOT EXISTS idx_rel_classe ON public.relation_ndvi_chirps_mensuelle(classe_relation);

